class Solution {public:vector<int> countMentions(int numberOfUsers,vector<vector<string>>& events){
 sort(events.begin(),events.end(),[](const vector<string>&a,const vector<string>&b){int x=stoi(a[1]),y=stoi(b[1]);if(x!=y)return x<y;return a[0]=="OFFLINE"&&b[0]!="OFFLINE";});
 vector<int>ans(numberOfUsers),back(numberOfUsers,0);for(auto&e:events){int t=stoi(e[1]);if(e[0]=="OFFLINE"){back[stoi(e[2])]=t+60;continue;}
 if(e[2]=="ALL"){for(int&i:ans)++i;}else if(e[2]=="HERE"){for(int i=0;i<numberOfUsers;++i)if(back[i]<=t)++ans[i];}
 else {stringstream ss(e[2]);string x;while(ss>>x)++ans[stoi(x.substr(2))];}}
 return ans;
}};
